import { expect, expectStatus, test, type Document } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review whose insurance certificate expired yesterday.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await factory.upload(vendor.id, "contract", "contract.txt", "member");

  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const insuranceText = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`;
  const insurance = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance.txt", mimeType: "text/plain", buffer: Buffer.from(insuranceText) },
      },
    }),
    201,
  );

  let documents: Document[] = [];
  await expect
    .poll(
      async () => {
        documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const extraction = await factory.extraction(insurance.id, "reviewer");

  // Act: the reviewer approves the expired insurance certificate.
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  // Re-read the stored state: the refused approval must not have been saved.
  expect((await factory.extraction(insurance.id, "reviewer")).status).toBe("pending_review");
});
